import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

import { fleetVehicleIds, legacyVehicleSeeds } from '@adatechnology/game-vehicles-fleet'

import { extractCards, extractLightFleet, extractRegisters } from './extract'
import { GAME_SLICE_DIR, GARAGE_ARTIFACT_DIR, OUTPUT_PATHS } from './paths'

/** Generated files by absolute path, each with its exact content. */
export type CatalogFiles = Readonly<Record<string, string>>

const serialize = (data: unknown): string => `${JSON.stringify(data, null, 2)}\n`

const sdkIdByPageKey = (): Record<string, string> => Object.fromEntries(Object.entries(legacyVehicleSeeds).map(([id, key]) => [key, id]))

const fail = (message: string): never => {
  throw new Error(`vehicles-catalog: ${message}`)
}

/** Vehicle id to the card of the Frota document: the card is found by the display name the Garagem registers for the vehicle. */
const cardsById = () => {
  const ids = sdkIdByPageKey()
  const cards = extractCards()
  const registers = extractRegisters()
  const byId = new Map<string, (typeof cards)[number]>()
  for (const card of cards) {
    const register = registers.find((entry) => entry.name === card.n) ?? fail(`no vehicle registered with the name "${card.n}"`)
    const id = ids[register.key] ?? fail(`page key "${register.key}" has no SDK id in legacyVehicleSeeds`)
    if (byId.has(id)) fail(`two cards for "${id}"`)
    byId.set(id, card)
  }
  for (const id of fleetVehicleIds) if (!byId.has(id)) fail(`no card for "${id}"`)
  return byId
}

export const buildCatalog = (): CatalogFiles => {
  const ids = sdkIdByPageKey()
  const light = extractLightFleet()
  const dims: Record<string, { length: number; width: number; height: number }> = {}
  for (const id of fleetVehicleIds) {
    const entry = light.dims.find((candidate) => candidate.k === legacyVehicleSeeds[id]) ?? fail(`no DIMS for "${id}"`)
    dims[id] = { length: entry.L, width: entry.W, height: entry.H }
  }
  for (const entry of light.dims) if (!ids[entry.k]) fail(`DIMS has "${entry.k}" with no SDK id`)

  const cards = cardsById()
  const stats: Record<string, unknown> = {}
  const texts: Record<string, unknown> = {}
  for (const id of fleetVehicleIds) {
    const card = cards.get(id) ?? fail(`no card for "${id}"`)
    const [speed, acceleration, handling, toughness, load, consumption] = card.s
    stats[id] = { speed, acceleration, handling, toughness, load, consumption, noiseRadius: card.r, maxSpeedKmh: card.vmax }
    texts[id] = {
      name: card.n,
      kind: card.c,
      description: card.d,
      inspiredBy: card.insp,
      seats: card.seats,
      tank: card.tank,
      efficiency: card.eff,
      fuel: card.fuel,
      autonomy: card.auto,
      tags: card.tags,
    }
  }
  return {
    [OUTPUT_PATHS.dims]: serialize(dims),
    [OUTPUT_PATHS.paint]: serialize({ civil: light.palette, military: light.militaryPalette }),
    [OUTPUT_PATHS.stats]: serialize(stats),
    [OUTPUT_PATHS.cardsPtBr]: serialize(texts),
  }
}

const SLICE_FILES = [['zombiada/plugin.js', 'plugin.js']] as const
const SLICE_README = `# Vehicles slice for the zombiada repository

\`plugin.js\` is the Garagem artifact's game plugin, copied as delivered. It is game content, not SDK: zombie blood as a fluid, the horde
scenario and the front blood effect, plate \`ZMB4D23\`, the 14 zone texts and the fuel effects written for the Vale Cinzento. The generic parts
(fuels, groups, damage scenarios) already live in \`@adatechnology/game-vehicles-fleet\`.

Generated by \`pnpm --filter @adatechnology/vehicles-catalog-tool catalog:game\`.
`

export const buildGameSlice = (): CatalogFiles => {
  const files: Record<string, string> = {}
  for (const [from, to] of SLICE_FILES) files[join(GAME_SLICE_DIR, to)] = readFileSync(join(GARAGE_ARTIFACT_DIR, from), 'utf8')
  files[join(GAME_SLICE_DIR, 'README.md')] = SLICE_README
  return files
}

export const staleFiles = (files: CatalogFiles): string[] =>
  Object.entries(files)
    .filter(([path, content]) => !existsSync(path) || readFileSync(path, 'utf8') !== content)
    .map(([path]) => path)

export const writeFiles = (files: CatalogFiles): void => {
  for (const [path, content] of Object.entries(files)) {
    mkdirSync(dirname(path), { recursive: true })
    writeFileSync(path, content)
  }
}

